import { useState, useEffect, Fragment } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { Listbox, Transition } from '@headlessui/react';
import PhoneInput from 'react-phone-input-2';
import toast from 'react-hot-toast';
import 'react-phone-input-2/lib/style.css';
import { api } from '../../utils/api';

// Importing icons for a better UI
import { User, Phone, Mail, Lock, Building, ChevronDown, Check, Loader2, Eye, EyeOff } from 'lucide-react';

const RegisterPage = () => {
    const navigate = useNavigate();

    // --- State Management ---
    const [formData, setFormData] = useState({
        role: 'Company',
        name: '',
        phone: '',
        email: '',
        category: '',
        country: '',
        password: '',
        confirmPassword: '',
        referralCode: '',
        termsAccepted: false,
    });

    const [countries, setCountries] = useState([]);
    const [loading, setLoading] = useState(false);
    const [initialCountry, setInitialCountry] = useState('us');
    const [showPassword, setShowPassword] = useState(false);
    const [showConfirmPassword, setShowConfirmPassword] = useState(false);

    useEffect(() => {
        const fetchUserCountry = async () => {
            try {
                const response = await fetch('https://ipinfo.io/json?token=6b3f765fe8dfe5');
                if (!response.ok) throw new Error('Failed to fetch IP info.');
                const data = await response.json();
                setInitialCountry(data.country.toLowerCase());
            } catch (err) {
                console.error("Could not fetch user's country:", err);
                setInitialCountry('us');
            }
        };
        fetchUserCountry();
    }, []);

    useEffect(() => {
        const fetchCountries = async () => {
            try {
                const response = await fetch('https://countriesnow.space/api/v0.1/countries');
                if (!response.ok) throw new Error('Failed to fetch country list.');
                const data = await response.json();
                if (data.error) throw new Error(data.msg);
                const countryNames = data.data.map(c => c.country).sort();
                setCountries(countryNames);
            } catch (err) {
                console.error("Failed to fetch countries:", err);
                toast.error("Could not load country list.");
            }
        };
        fetchCountries();
    }, []);

    const categories = [
        'Freight Forwarders', 'Third-Party Logistics Providers (3PLs)', 'Courier and Parcel Delivery Services',
        'Warehousing and Distribution', 'Transportation Service', 'Supply Chain Management', 'Inventory Management',
        'Cold Chain Logistics', 'Reverse Logistics', 'E-commerce Logistics', 'Cross-border Logistics',
        'Specialized Logistics', 'Technology and Software Providers', 'Packaging and Labeling Services',
        'Last-Mile Delivery and Urban Logistics', 'Air Cargo and Freight Services', 'Rail and Intermodal Logistics',
        'Freight Brokerage', 'Drone and Autonomous Vehicle Logistics', 'Custom Brokerage'
    ];
    
    const roles = ['Company', 'Business'];

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData(prevState => ({
            ...prevState,
            [name]: type === 'checkbox' ? checked : value,
        }));
    };
    
    const handlePhoneChange = (phone) => {
        setFormData(prevState => ({ ...prevState, phone }));
    };

    const handleCountryChange = (country) => {
        setFormData(prevState => ({ ...prevState, country }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        
        if (formData.password !== formData.confirmPassword) {
            toast.error('Passwords do not match.');
            return;
        }
        if (!formData.termsAccepted) {
            toast.error('You must accept the Terms and Conditions.');
            return;
        }

        setLoading(true);
        try {
            const data = await api.post('/api/user/register', {
                ...formData,
                role: formData.role.toLowerCase(),
            });

            // --- SUCCESS FLOW: Show message and redirect to login ---
            if (data.accountStatus === 'pending_approval') {
                toast.success(data.message || 'Account created! Your account is pending admin approval.');
                
                // Navigate to login page after a short delay
                setTimeout(() => {
                    navigate('/login');
                }, 3000);
            } else {
                // Fallback for other success cases
                toast.success('Account created successfully!');
                navigate('/login');
            } 

        } catch (err) {
            toast.error(err.message || 'An unexpected error occurred.');
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="bg-stone-50 mt-20 min-h-screen font-sans">
            <header
                className="h-60 bg-cover bg-center relative"
                style={{ backgroundImage: `url('/Login.jpg')` }}
            >
                <div className="container mx-auto h-full flex flex-col justify-center items-center text-white relative z-10">
                    <h1 className="text-5xl font-bold tracking-tight">Register</h1>
                    <p className="mt-2 text-lg">
                        <span>Home</span><span className="mx-2">&gt;</span><span>Register</span>
                    </p>
                </div>
            </header>
            
            <main className="container mt-44 mx-auto px-4 py-16">
                <div className="bg-white p-8 md:p-12 rounded-2xl shadow-xl max-w-2xl mx-auto -mt-48 relative z-20 border border-gray-100">
                    <h2 className="text-3xl font-bold text-gray-800 mb-2">Create Your Account!</h2>
                    <div className="w-24 h-1.5 bg-[#CDA435] rounded-full mb-8"></div>
                    
                    <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">
                        
                        <CustomSelect
                            label="I am a *"
                            value={formData.role}
                            onChange={(val) => handleChange({ target: { name: 'role', value: val } })}
                            options={roles}
                            placeholder="Select a Role"
                        />

                        <InputWithIcon id="name" name="name" type="text" value={formData.name} onChange={handleChange} placeholder="Enter Your Full Name" required icon={<User className="w-5 h-5 text-gray-400" />} />
                        
                        <div>
                            <label htmlFor="phone" className="block text-gray-700 text-sm font-medium mb-2">Phone *</label>
                            <PhoneInput
                                country={initialCountry}
                                value={formData.phone}
                                onChange={handlePhoneChange}
                                inputProps={{ name: 'phone', required: true }}
                                containerClass="w-full"
                                inputStyle={{ width: '100%', height: '40px', border: '1px solid #D1D5DB', color: '#4B5563' }}
                                buttonClass="bg-stone-100 border-r border-stone-200 rounded-l-lg"
                                dropdownClass="rounded-lg shadow-lg"
                            />
                        </div>

                        <InputWithIcon id="email" name="email" type="email" value={formData.email} onChange={handleChange} placeholder="Enter Your Email" required icon={<Mail className="w-5 h-5 text-gray-400" />} />

                        <CustomSelect
                            label="Category *"
                            value={formData.category}
                            onChange={(val) => handleChange({ target: { name: 'category', value: val } })}
                            options={categories}
                            placeholder="Select a Category"
                        />
                        
                        <CustomSelect
                            label="Country *"
                            value={formData.country}
                            onChange={handleCountryChange}
                            options={countries}
                            placeholder="Select a Country"
                        />

                        <InputWithIcon 
                            id="password" 
                            name="password" 
                            type={showPassword ? 'text' : 'password'}
                            value={formData.password} 
                            onChange={handleChange} 
                            placeholder="Create a Password" 
                            required 
                            icon={<Lock className="w-5 h-5 text-gray-400" />}
                            showPassword={showPassword}
                            togglePassword={() => setShowPassword(!showPassword)}
                        />
                        <InputWithIcon 
                            id="confirmPassword" 
                            name="confirmPassword" 
                            type={showConfirmPassword ? 'text' : 'password'}
                            value={formData.confirmPassword} 
                            onChange={handleChange} 
                            placeholder="Confirm Password" 
                            required 
                            icon={<Lock className="w-5 h-5 text-gray-400" />}
                            showPassword={showConfirmPassword}
                            togglePassword={() => setShowConfirmPassword(!showConfirmPassword)}
                        />
                        
                        <div className="md:col-span-2">
                             <InputWithIcon id="referralCode" name="referralCode" type="text" value={formData.referralCode} onChange={handleChange} placeholder="Enter Referral Code (Optional)" icon={<Building className="w-5 h-5 text-gray-400" />} />
                        </div>
                        
                        <div className="md:col-span-2 flex items-center">
                            <input id="termsAccepted" name="termsAccepted" type="checkbox" checked={formData.termsAccepted} onChange={handleChange} className="h-4 w-4 rounded border-gray-300 accent-[#CDA435] focus:ring-[#CDA435]" />
                            <label htmlFor="termsAccepted" className="ml-3 block text-sm text-gray-800">I accept the <a href="#" className="font-medium text-[#CDA435] hover:underline">Terms and Conditions</a></label>
                        </div>
                        
                        <div className="md:col-span-2">
                            <button
                                type="submit"
                                disabled={loading}
                                className="w-full flex justify-center items-center gap-2 cursor-pointer py-3 px-4 mt-4 rounded-lg shadow-sm text-base font-semibold text-white bg-[#CDA435] hover:bg-opacity-90 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#CDA435] transition-all disabled:bg-gray-400 disabled:cursor-not-allowed"
                            >
                                {loading && <Loader2 className="w-5 h-5 animate-spin" />}
                                {loading ? 'Registering...' : 'Create Account'}
                            </button>
                        </div>

                    </form>
                                            <p className='text-md mt-8 text-center'>
                                          Need to track quotes?{' '}
                                          <Link 
                                              to="/user-register" 
                                              
                                              className="font-semibold text-[#CDA435] underline hover:text-[#CDA435]"
                                          >
                                              Create User Account
                                          </Link>
                                      </p>
                </div>
            </main>
        </div>
    );
};

// --- Helper components ---
const InputWithIcon = ({ id, name, type = 'text', value, onChange, placeholder, required = false, icon, showPassword, togglePassword }) => (
    <div>
        <label htmlFor={id} className="block text-gray-700 text-sm font-medium mb-2">
            {placeholder.replace('Enter Your ', '').replace('Create a ', '').replace(' (Optional)', '')} {required && '*'}
        </label>
        <div className="relative">
            <span className="absolute inset-y-0 left-0 flex items-center pl-3 pointer-events-none">
                {icon}
            </span>
            <input
                type={type} id={id} name={name} value={value} onChange={onChange}
                placeholder={placeholder} required={required}
                className="w-full pl-10 pr-12 py-3 bg-stone-100 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#CDA435] border-transparent transition"
            />
            {(type === 'password' || (type === 'text' && togglePassword)) && (
                <button
                    type="button"
                    onClick={togglePassword}
                    className="absolute inset-y-0 right-0 flex items-center pr-3 text-gray-400 hover:text-gray-600"
                    aria-label="Toggle password visibility"
                >
                    {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                </button>
            )}
        </div>
    </div>
);


const CustomSelect = ({ label, value, onChange, options, placeholder, disabled = false, loading = false }) => (
    <div>
        <Listbox value={value} onChange={onChange} disabled={disabled}>
            <Listbox.Label className="block text-gray-700 text-sm font-medium mb-2">{label}</Listbox.Label>
            <div className="relative">
                <Listbox.Button className="relative w-full cursor-default rounded-lg bg-stone-100 py-3 pl-3 pr-10 text-left focus:outline-none focus-visible:ring-2 focus-visible:ring-[#CDA435] disabled:bg-stone-200 disabled:cursor-not-allowed">
                    <span className={`block truncate ${value ? 'text-gray-900' : 'text-gray-400'}`}>
                        {value || placeholder}
                    </span>
                    <span className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-2">
                        {loading ? <Loader2 className="h-5 w-5 text-gray-400 animate-spin" /> : <ChevronDown className="h-5 w-5 text-gray-400" aria-hidden="true" />}
                    </span>
                </Listbox.Button>
                <Transition as={Fragment} leave="transition ease-in duration-100" leaveFrom="opacity-100" leaveTo="opacity-0">
                    <Listbox.Options className="absolute mt-1 max-h-60 w-full overflow-auto rounded-md bg-white py-1 text-base shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none sm:text-sm z-30">
                        {options.length === 0 && !loading ? (
                            <div className="relative cursor-default select-none py-2 px-4 text-gray-700">Nothing found.</div>
                        ) : (
                            options.map((option, optionIdx) => (
                                <Listbox.Option
                                    key={optionIdx}
                                    className={({ active }) => `relative cursor-default select-none py-2 pl-10 pr-4 ${active ? 'bg-[#f0e4c2] text-[#8e7121]' : 'text-gray-900'}`}
                                    value={option}
                                >
                                    {({ selected }) => (
                                        <>
                                            <span className={`block truncate ${selected ? 'font-medium' : 'font-normal'}`}>{option}</span>
                                            {selected ? (
                                                <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-[#CDA435]">
                                                    <Check className="h-5 w-5" aria-hidden="true" />
                                                </span>
                                            ) : null}
                                        </>
                                    )}
                                </Listbox.Option>
                            ))
                        )}
                    </Listbox.Options>
                </Transition>
            </div>
        </Listbox>
    </div>
);


export default RegisterPage;